target.query:
from(bucket: "otlp_metric")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r["_measurement"] == "cpu")
  |> filter(fn: (r) => r["dsname"] == "gauge")
  //|> filter(fn: (r) => r["host"] == "49392966-ba6d-40e3-aba5-9ca7c82ee0a5")
  //|> filter(fn: (r) => r["interval"] == "5")
  |> filter(fn: (r) => r["plugin"] == "cpu")
  |> filter(fn: (r) => r["plugin_instance"] == "0" or r["plugin_instance"] == "1" or r["plugin_instance"] == "2" or r["plugin_instance"] == "3")
  |> filter(fn: (r) => r["type_instance"] == "system")
  |> aggregateWindow(every: v.windowPeriod, fn: mean, createEmpty: false)
  //|> group()
  |> yield(name: "mean")
  |> max(column: "_value")

