select max_by(from_iso8601_timestamp(time),rx) max_time, max(cast(rx as int))*${unit_change_bit} rx, 'max_rx' as title
from(
select case
           when '${type_hub}' = 'if_packets' then 'pps'
           when '${type_hub}' = 'if_octets' then 'bps'
           else '' end                as Unit,
       time,
       (sum(tx) * ${unit_change_bit}) as tx,
       (sum(rx) * ${unit_change_bit}) as rx
from (select time,host,iface,
             (avg(tx / duration)) as tx,
             (avg(rx / duration)) as rx
      from (select time,
                   q.host,
                   q.iface,
                   (max_tx - min_tx) as tx,
                   (max_rx - min_rx) as rx,
                   duration
            from (
                  ${view_interface_with_all_hubs_and_type_filter:text}
            ) as q
            left join (
                  ${view_tenant_host_overlay_iface:text}
            ) as s on q.host = s.host AND s.iface like  q.iface|| '%' 
            -- AND q.iface = s.iface 
            where time is not null AND s.islanif = 'false') as r
      group by time, r.host, r.iface) as q
group by time
order by time
)as t

select date_add('second', 2, max_by(from_iso8601_timestamp(time),tx)) max_time, max(cast(tx as int))*${unit_change_bit} tx, 'max_tx' as title
from(
select case
           when '${type_hub}' = 'if_packets' then 'pps'
           when '${type_hub}' = 'if_octets' then 'bps'
           else '' end                as Unit,
       time,
       (sum(tx) * ${unit_change_bit}) as tx,
       (sum(rx) * ${unit_change_bit}) as rx
from (select time,host,iface,
             (avg(tx / duration)) as tx,
             (avg(rx / duration)) as rx
      from (select time,
                   q.host,
                   q.iface,
                   (max_tx - min_tx) as tx,
                   (max_rx - min_rx) as rx,
                   duration
            from (
                  ${view_interface_with_all_hubs_and_type_filter:text}
            ) as q
            left join (
                  ${view_tenant_host_overlay_iface:text}
            ) as s on q.host = s.host AND s.iface like  q.iface|| '%' 
