options.afterRender:
const currentUrl = window.location.href;

// ?orgId önceki kısım
const urlBeforeOrgId = currentUrl.split('?orgId')[0];

//?orgId önceki kısım ve "/" karakterinden sonrası
const pathAfterSlash = urlBeforeOrgId.substring(urlBeforeOrgId.lastIndexOf('/') + 1);

// "Flow" ve "Detail" kısmını al
const pathParts = pathAfterSlash.split('-');

// Başlığı oluşturan kısım
const formattedTitle = `${pathParts[0].charAt(0).toUpperCase() + pathParts[0].slice(1)} ${pathParts[1].charAt(0).toUpperCase() + pathParts[1].slice(1)}`;

// HTML'deki başlık 
const titleElement = document.getElementById('title');
const urlParams = new URLSearchParams(window.location.search);
//const siteName = urlParams.get('var-sites');

if (titleElement) {
  // var-sites varsa, başlıkla birlikte site adını ekle
  // if (siteName) {
  //   titleElement.textContent = `${formattedTitle} ${siteName}`;
  // } else { }
    titleElement.textContent = formattedTitle;

}

